(()=>{
const params=new URLSearchParams(location.search);const qr=params.get('qr');if(!qr)return;
localStorage.removeItem('stolovaya:web-token');
state.qrToken=qr;state.qrInfo=null;state.employeeId='';state.employeeName='';state.isAdmin=false;state.kioskPoint='';
const baseRender=render,baseBind=bind,baseHome=homeScreen,baseHeader=header;
function employeeScreen(){const info=state.qrInfo;if(!info)return `<section class="access-card"><div class="brand-login">Столовая</div><h1>Вход на точку</h1><p>${state.busy?'Загружаем сотрудников…':'Не удалось загрузить сотрудников'}</p>${state.message?`<p class="error-text">${esc(state.message)}</p>`:''}</section>`;return `<section class="access-card"><div class="brand-login">Столовая</div><h1>${esc(info.pointName)}</h1><p>Выберите своё ФИО. Без выбора сотрудника вход невозможен.</p><div class="point-choice-list">${(info.employees||[]).map(e=>`<button class="employee-choice" data-employee="${esc(e.id)}">${esc(e.fullName)}${e.isAdmin?' · администратор':''}</button>`).join('')}</div>${!(info.employees||[]).length?'<p class="error-text">Для этой точки пока не назначены сотрудники.</p>':''}</section>`}
render=function(){if(state.screen==='employee-login'){app.innerHTML=employeeScreen();bind();return}baseRender()};
bind=function(){baseBind();document.querySelectorAll('.employee-choice').forEach(b=>b.onclick=()=>employeeLogin(b.dataset.employee));};
header=function(){const h=baseHeader();return state.employeeName?h.replace('</header>',`<div class="employee-chip">${esc(state.employeeName)}</div></header>`):h};
homeScreen=function(){let html=baseHome();if(!state.isAdmin){html=html.replace(/<button id="change-point"[\s\S]*?<\/button>/,'');}return html};
async function employeeLogin(id){state.busy=true;state.message='';render();try{const r=await rpc('public_point_employee_login',{p_qr_token:state.qrToken,p_employee_id:id});state.token=r.token;state.employeeId=id;state.employeeName=r.employeeName||'';state.isAdmin=!!r.isAdmin;state.kioskPoint=r.pointCode||'';sessionStorage.setItem('stolovaya:employee-name',state.employeeName);sessionStorage.setItem('stolovaya:is-admin',state.isAdmin?'1':'0');if(state.isAdmin){localStorage.setItem('stolovaya:web-token',state.token);await loadPoints();state.screen='point';render();}else{state.points=await rpc('public_point_options',{p_token:state.token});await choosePoint(state.kioskPoint);document.querySelector('.admin-entry')?.remove();}}catch(e){state.message=e.message||'Не удалось войти';state.screen='employee-login';render()}finally{state.busy=false}}
(async()=>{state.token='';state.screen='employee-login';state.busy=true;render();try{state.qrInfo=await rpc('public_point_qr_start',{p_qr_token:state.qrToken});state.message=''}catch(e){state.message=e.message||'QR-код недействителен'}finally{state.busy=false;render()}})();
})();